    "meetings.type_closeout": "Zatvaranje",
    "meetings.type_closeout_desc": "Zatvaranje i primopredaja projekta",
    "meetings.type_commercial": "Obračun",
    "meetings.type_commercial_desc": "Obračun, izmjene i pregled troškova",
